{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:opensip:design:private-attempt-custody:1",
  "title": "PROPOSED private AttemptCustodyV1 (ledger-owned monotone attempt phase and outcome)",
  "status": "PROPOSED-NOT-SELF-ACCEPTED",
  "standing": "Design/reference proposal only: no acceptance, no readiness, no application and no implementation authorization. Private local operational record. Not a public request, wire schema, authority token or extension to any Run/receipt/journal schema.",
  "revisionNote": "Corrects the v4 draft. v4 defined settledOutcome but its read-only recovery Step 1 branched on phase alone, so a settled row whose outcome was committed or undetermined could be read as terminal-not-committed. That was wrong: a settled-committed row with no receipt is a contradiction, and an undetermined outcome proves nothing about absence. Phase/outcome coupling, the exact joins and the negative-conclusion rule are now normative below.",
  "canonicalProfile": {
    "selected": "product / foundation canonicalizer of identity-and-evidence section 3",
    "rules": "no normalization, integers to 2^64-1, H(domain, descriptor) where a domain digest is taken, raw SHA-256 over the exact canonical bytes where a plain digest is taken",
    "notSelected": "opensip-metadata-canonical.1",
    "why": "Security section S2 splits the two profiles and states that a decoder for one never admits the other's documents. The metadata profile covers signed security metadata: root, catalog, revocation, JOURNAL RECORDS, recovery challenge and epoch, and platform profile population. This record is none of those. It is private storage/ledger operational metadata in the same family as CommitRecoveryAssociationV1, whose storeGenerationDigest is already a raw SHA-256 over canonical bytes.",
    "contrastToStateExplicitly": "The journal body_sha256 this record joins against IS domain-framed under opensip.metadata.journal.1. This record's own digests are NOT. Conflating the two is the exact error the earlier followup predicate made, so the two profiles are named at every join."
  },
  "type": "object",
  "additionalProperties": false,
  "required": [
    "recordSchema",
    "storeGenerationDigest",
    "namespaceId",
    "executionId",
    "operationRef",
    "phase",
    "settledOutcome"
  ],
  "properties": {
    "recordSchema": {
      "description": "Constant 1; reject unknown versions before any join.",
      "type": "integer",
      "const": 1
    },
    "storeGenerationDigest": {
      "description": "Raw SHA-256 of the canonical private StoreGenerationBindingV1, exactly the value the private association uses. PS-01 owns the binding tuple and digest shape; this record consumes it and allocates nothing.",
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])"
    },
    "namespaceId": {
      "description": "Exact registered project namespace; binary equality, no path resolution.",
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
    },
    "executionId": {
      "description": "The reserved attempt ExecutionId, product successor grammar, end-anchored.",
      "type": "string",
      "pattern": "^exec1_[0-9a-f]{32}(?![\\s\\S])"
    },
    "operationRef": {
      "description": "The security-owned operation token for this attempt, keeping its own grammar. This is the durable home of the executionId-to-operationRef correlation for attempts that never commit, which is why no member is added to the closed schema-3 JournalRecord to correlate a pending REV.",
      "type": "string",
      "pattern": "^op-[0-9a-f]{32}(?![\\s\\S])"
    },
    "phase": {
      "description": "Monotone. admitted is written when the ExecutionId reservation is taken; settled is written by the guarded cleanup path or by the authorized settlement sweep. The only lawful transition is admitted to settled.",
      "enum": ["admitted", "settled"]
    },
    "settledOutcome": {
      "description": "Null exactly while phase is admitted. Records what happened; it authorizes nothing. See phaseOutcomeCoupling and negativeConclusionRule: only the refused outcome can ever support a negative conclusion.",
      "oneOf": [
        {"type": "null"},
        {"enum": ["committed", "refused", "undetermined"]}
      ]
    }
  },
  "allOf": [
    {
      "if": {"properties": {"phase": {"const": "admitted"}}, "required": ["phase"]},
      "then": {"properties": {"settledOutcome": {"type": "null"}}}
    },
    {
      "if": {"properties": {"phase": {"const": "settled"}}, "required": ["phase"]},
      "then": {"properties": {"settledOutcome": {"enum": ["committed", "refused", "undetermined"]}}}
    }
  ],
  "primaryKey": ["storeGenerationDigest", "namespaceId", "executionId"],
  "phaseOutcomeCoupling": {
    "admitted": "settledOutcome is null. The attempt is not terminal. No negative conclusion is available.",
    "settled+committed": "A receipt and association for this exact primary key MUST exist in the same coherent ledger snapshot. If they do not, that is a contradiction between two rows the same transaction family owns: report the contradiction and unavailable history. NEVER terminal-not-committed.",
    "settled+refused": "No receipt and no association exist for this primary key, and the guarded path that wrote this outcome observed that. This is the ONLY outcome that can support a negative conclusion, and only together with a confirmed absent receipt in the same snapshot.",
    "settled+undetermined": "The commit syscall or a required barrier was unconfirmed. The row records that the attempt STOPPED being live; it proves nothing about whether the evidence transaction committed. A negative conclusion is unavailable until an authorized reconciliation establishes actual absence or presence."
  },
  "negativeConclusionRule": {
    "statement": "terminal-not-committed requires ALL of: phase settled; settledOutcome exactly refused; no receipt row for the primary key; no association row for the primary key; all four observed in ONE coherent ledger snapshot.",
    "everythingElse": "unknown, never a negative",
    "forbidden": [
      "Concluding a negative from phase alone.",
      "Concluding a negative from settledOutcome undetermined.",
      "Concluding a negative from absence in an in-memory active set.",
      "Concluding a negative from two separately timed observations."
    ]
  },
  "purgedReceiptLaw": {
    "statement": "A historical receipt that was retained and later purged must NEVER become never-committed.",
    "mechanism": "Purge retains the minimal sealed manifest, provenance and tombstone (identity section 5). A settled+committed row whose receipt bytes are no longer present but whose retained manifest or tombstone still names the Run is COMMITTED with degraded availability, reported through the existing evidence availability vocabulary. Absence of receipt BYTES is not absence of a RECEIPT.",
    "consequence": "The negative conclusion rule therefore requires settledOutcome refused, which a purge can never produce, so no purge can ever flip a committed attempt to a negative."
  },
  "joins": {
    "toReceipt": "(storeGenerationDigest, namespaceId, executionId) equals the receipt's store binding, namespace and executionId, by binary equality.",
    "toAssociation": "the same three values are CommitRecoveryAssociationV1's primary key, so the association row is the same attempt by construction.",
    "toOperation": "operationRef equals the operationRef the association carries when an association exists, and is the sole durable correlation when it does not.",
    "toCarrier": "this record carries NO carrier field. The carrier join is the association's journalCarrierDigest, grantGeneration, journalSeq and journalBodySha256, where journalBodySha256 is the DOMAIN-FRAMED journal body digest, not a raw SHA-256."
  },
  "laws": [
    "Written only by the guarded commit facade, its cleanup path, or the authorized settlement sweep. Low-level row insertion stays private; no INSERT OR REPLACE, mutation-on-read, unchecked restore constructor or convenience API may bypass these invariants.",
    "admitted to settled is the only transition. Never reversed, never deleted, never re-opened, no second row for the same primary key, and settledOutcome is never rewritten once set.",
    "The settle write is ordered AFTER the receipt write, so one coherent ledger snapshot can never show settled+committed without a receipt that was committed earlier. This ordering is what makes a single snapshot sufficient and removes every separately timed liveness probe from read-only recovery.",
    "It authorizes nothing. Settling records an outcome and never licenses a retry, so the D9 law that a settled ExecutionId is terminal is preserved exactly. A later attempt after authority restoration receives a fresh ExecutionId.",
    "Read by read-only recovery in the SAME snapshot as the receipt and the association, never through a second separately timed query.",
    "Excluded from every semantic hash, Run identity, Coverage, Plan bound and public schema. It adds no field to the closed receipt or JournalRecord schemas."
  ],
  "proposedPrivateDDL": "CREATE TABLE attempt_custody (\n  store_generation_digest TEXT NOT NULL CHECK (length(store_generation_digest) = 64 AND store_generation_digest GLOB '[0-9a-f]*'),\n  namespace_id    TEXT NOT NULL CHECK (length(namespace_id) BETWEEN 1 AND 4096),\n  execution_id    TEXT NOT NULL CHECK (execution_id GLOB 'exec1_[0-9a-f]*' AND length(execution_id) = 38),\n  operation_ref   TEXT NOT NULL CHECK (operation_ref GLOB 'op-[0-9a-f]*' AND length(operation_ref) = 35),\n  record_schema   INTEGER NOT NULL CHECK (record_schema = 1),\n  phase           TEXT NOT NULL CHECK (phase IN ('admitted','settled')),\n  settled_outcome TEXT CHECK (settled_outcome IS NULL OR settled_outcome IN ('committed','refused','undetermined')),\n  CHECK ((phase = 'admitted' AND settled_outcome IS NULL)\n      OR (phase = 'settled'  AND settled_outcome IS NOT NULL)),\n  PRIMARY KEY (store_generation_digest, namespace_id, execution_id)\n) WITHOUT ROWID;\nCREATE TRIGGER ac_no_delete BEFORE DELETE ON attempt_custody\n  BEGIN SELECT RAISE(ABORT, 'attempt custody is append-and-settle only'); END;\nCREATE TRIGGER ac_monotone BEFORE UPDATE ON attempt_custody\n  BEGIN\n    SELECT CASE WHEN OLD.phase = 'settled'\n      THEN RAISE(ABORT, 'attempt custody is already settled') END;\n    SELECT CASE WHEN NEW.phase <> 'settled' OR NEW.settled_outcome IS NULL\n      THEN RAISE(ABORT, 'the only lawful transition is admitted to settled') END;\n    SELECT CASE WHEN NEW.store_generation_digest <> OLD.store_generation_digest\n              OR NEW.namespace_id <> OLD.namespace_id\n              OR NEW.execution_id <> OLD.execution_id\n              OR NEW.operation_ref <> OLD.operation_ref\n              OR NEW.record_schema <> OLD.record_schema\n      THEN RAISE(ABORT, 'attempt custody identity is immutable') END;\n  END;\n",
  "ddlStanding": "Proposed private DDL for the evidence ledger, offered because root asked for it if needed. It is storage-owned; if root's storage session prefers a different physical placement the record shape and laws above are what must survive, not this SQL.",
  "readOnlyRecoveryUse": {
    "receiptPresentAndPhaseSettledCommitted": "proceed to the carrier capture and anchor selection",
    "receiptPresentAndPhaseAdmitted": "contradiction: a receipt exists but the attempt was never settled; report unavailable history, never a negative",
    "receiptAbsentAndPhaseSettledRefused": "terminal-not-committed",
    "receiptAbsentAndPhaseSettledCommitted": "contradiction: report unavailable history, never a negative",
    "receiptAbsentAndPhaseSettledUndetermined": "unknown-attempt-undetermined; requires authorized reconciliation, not a read-only negative",
    "receiptAbsentAndPhaseAdmitted": "unknown-attempt-open",
    "receiptAbsentAndNoRow": "unknown-attempt-unobserved",
    "exactlyOneOfReceiptOrAssociation": "unknown-custody contradiction (F23); synthesize nothing"
  },
  "notEstablished": [
    "No OS durability, fsync behaviour or real crash behaviour for this row.",
    "The proposed DDL was executed only against in-memory SQLite for its constraint and trigger behaviour; no on-disk ledger was created or migrated."
  ]
}

